//! Raw FFI bindings to [LibRaw](https://www.libraw.org/).
//!
//! Generated by `bindgen` at build time from `libraw/libraw.h` (the C API).
//! Prefer the safe wrapper in the `libraw-dev` crate over these directly.
#![allow(non_upper_case_globals)]
#![allow(non_camel_case_types)]
#![allow(non_snake_case)]
#![allow(dead_code)]
#![allow(rustdoc::broken_intra_doc_links)]

include!(concat!(env!("OUT_DIR"), "/bindings.rs"));
